1: # @apm-js-collab/code-transformer-bundler-plugins
2: 
3: A universal plugin that uses
4: [`@apm-js-collab/code-transformer`](https://github.com/apm-js-collab/orchestrion-js)
5: to instrument JavaScript code at build time for application performance
6: monitoring and tracing.
7: 
8: **Compatible with Rollup, Webpack, Vite, esbuild, Bun, and more!**
9: 
10: ## Installation
11: 
12: ```bash
13: npm install @apm-js-collab/code-transformer-bundler-plugins
14: # or
15: yarn add @apm-js-collab/code-transformer-bundler-plugins
16: # or
17: pnpm add @apm-js-collab/code-transformer-bundler-plugins
18: ```
19: 
20: ## Usage
21: 
22: ### Rollup
23: 
24: ```javascript
25: // rollup.config.js
26: import codeTransformer from "@apm-js-collab/code-transformer-bundler-plugins/rollup";
27: 
28: export default {
29:   input: "src/index.js",
30:   output: {
31:     file: "dist/bundle.js",
32:     format: "esm",
33:   },
34:   plugins: [
35:     codeTransformer({
36:       instrumentations: [
37:         {
38:           channelName: "fetch:request",
39:           module: {
40:             name: "undici",
41:             versionRange: ">=5.0.0",
42:             filePath: "index.js",
43:           },
44:           functionQuery: {
45:             className: "Undici",
46:             methodName: "fetch",
47:             kind: "Async",
48:           },
49:         },
50:       ],
51:     }),
52:   ],
53: };
54: ```
55: 
56: ### Webpack
57: 
58: ```javascript
59: // webpack.config.js
60: const codeTransformer = require(
61:   "@apm-js-collab/code-transformer-bundler-plugins/webpack",
62: );
63: 
64: module.exports = {
65:   entry: "./src/index.js",
66:   plugins: [
67:     codeTransformer({
68:       instrumentations: [
69:         // ... your instrumentations
70:       ],
71:     }),
72:   ],
73: };
74: ```
75: 
76: ### Vite
77: 
78: ```javascript
79: // vite.config.js
80: import { defineConfig } from "vite";
81: import codeTransformer from "@apm-js-collab/code-transformer-bundler-plugins/vite";
82: 
83: export default defineConfig({
84:   plugins: [
85:     codeTransformer({
86:       instrumentations: [
87:         // ... your instrumentations
88:       ],
89:     }),
90:   ],
91: });
92: ```
93: 
94: ### esbuild
95: 
96: ```javascript
97: // build.js
98: import { build } from "esbuild";
99: import codeTransformer from "@apm-js-collab/code-transformer-bundler-plugins/esbuild";
100: 
101: build({
102:   entryPoints: ["src/index.js"],
103:   bundle: true,
104:   plugins: [
105:     codeTransformer({
106:       instrumentations: [
107:         // ... your instrumentations
108:       ],
109:     }),
110:   ],
111: });
112: ```
113: 
114: ### Bun Build
115: 
116: ```javascript
117: // build.ts
118: import codeTransformer from "@apm-js-collab/code-transformer-bundler-plugins/bun";
119: 
120: await Bun.build({
121:   entrypoints: ["src/index.ts"],
122:   plugins: [
123:     codeTransformer({
124:       instrumentations: [
125:         // ... your instrumentations
