1: import {
2:     create,
3:     type InstrumentationConfig,
4:     type ModuleType,
5: } from '@apm-js-collab/code-transformer';
6: import { extname, join } from 'path';
7: import { readFileSync } from 'fs';
8: import * as moduleDetailsFromPathImport from 'module-details-from-path';
9: import type { ModuleDetails } from 'module-details-from-path';
10: import { initSync as lexerInitSync, parse as lexerParse } from 'es-module-lexer';
11: 
12: const moduleDetailsFromPath: (filepath: string) => ModuleDetails =
13:     (moduleDetailsFromPathImport as any).default ||
14:     (moduleDetailsFromPathImport as any);
15: 
16: type Diagnostics = {
17:   transformedModules: string[];
18:   failedModules: string[];
19: };
20: 
21: // We need to be careful not to inject the snippet before any `"use strict";`s.
22: // As an additional complication `"use strict";`s may come after any number of comments.
23: export const COMMENT_USE_STRICT_REGEX =
24:   // Note: CodeQL complains that this regex potentially has n^2 runtime. This likely won't affect realistic files.
25:   /^(?:\s*|\/\*(?:.|\r|\n)*?\*\/|\/\/.*[\n\r])*(?:"[^"]*";|'[^']*';)?/;
26: 
27: function stripQueryAndHashFromPath(path: string): string {
28:   // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
29:   return path.split("?")[0]!.split("#")[0]!;
30: }
31: 
32: /**
33:  * Checks if a file is a JavaScript file based on its extension.
34:  * Handles query strings and hashes in the filename.
35:  */
36: export function isJsFile(fileName: string): boolean {
37:   const cleanFileName = stripQueryAndHashFromPath(fileName);
38:   return [".js", ".mjs", ".cjs"].some((ext) => cleanFileName.endsWith(ext));
39: }
40: 
41: /**
42:  * Checks if a chunk contains only import/export statements and no substantial code.
43:  *
44:  * In Vite MPA (multi-page application) mode, HTML entry points create "facade" chunks
45:  * that only contain import statements to load shared modules. These should not have
46:  * Sentry code injected. However, in SPA mode, the main bundle also has an HTML facade
47:  * but contains substantial application code that SHOULD have debug IDs injected.
48:  *
49:  * @ref https://github.com/getsentry/sentry-javascript-bundler-plugins/issues/829
50:  * @ref https://github.com/getsentry/sentry-javascript-bundler-plugins/issues/839
51:  */
52: export function containsOnlyImports(code: string): boolean {
53:   const codeWithoutImports = code
54:     // Remove side effect imports: import '/path'; or import "./path";
55:     // Using explicit negated character classes to avoid polynomial backtracking
56:     .replace(/^\s*import\s+(?:'[^'\n]*'|"[^"\n]*"|`[^`\n]*`)[\s;]*$/gm, "")
57:     // Remove named/default imports: import x from '/path'; import { x } from '/path';
58:     .replace(/^\s*import\b[^'"`\n]*\bfrom\s+(?:'[^'\n]*'|"[^"\n]*"|`[^`\n]*`)[\s;]*$/gm, "")
59:     // Remove re-exports: export * from '/path'; export { x } from '/path';
60:     .replace(/^\s*export\b[^'"`\n]*\bfrom\s+(?:'[^'\n]*'|"[^"\n]*"|`[^`\n]*`)[\s;]*$/gm, "")
61:     // Remove block comments
62:     .replace(/\/\*[\s\S]*?\*\//g, "")
63:     // Remove line comments
64:     .replace(/\/\/.*$/gm, "")
65:     // Remove "use strict" directives
66:     .replace(/["']use strict["']\s*;?/g, "")
67:     .trim();
68: 
69:   return codeWithoutImports.length === 0;
70: }
71: 
72: /**
73:  * Checks if a chunk should be skipped for code injection
74:  *
75:  * This is necessary to handle Vite's MPA (multi-page application) mode where
76:  * HTML entry points create "facade" chunks that should not contain injected code.
77:  * See: https://github.com/getsentry/sentry-javascript-bundler-plugins/issues/829
78:  *
79:  * However, in SPA mode, the main bundle also has an HTML facade but contains
80:  * substantial application code. We should NOT skip injection for these bundles.
81:  *
82:  * @param code - The chunk's code content
83:  * @param facadeModuleId - The facade module ID (if any) - HTML files create facade chunks
84:  * @returns true if the chunk should be skipped
85:  */
86: export function shouldSkipCodeInjection(
87:   code: string,
88:   facadeModuleId: string | null | undefined,
89: ): boolean {
90:   // Skip empty chunks - these are placeholder chunks that should be optimized away
91:   if (code.trim().length === 0) {
92:     return true;
93:   }
94: 
95:   // For HTML facade chunks, only skip if they contain only import statements
96:   if (
97:     facadeModuleId &&
98:     stripQueryAndHashFromPath(facadeModuleId).endsWith(".html")
99:   ) {
100:     return containsOnlyImports(code);
101:   }
102: 
103:   return false;
104: }
105: 
106: export interface CodeTransformerPluginOptions {
107:   /** Array of instrumentation configurations */
108:   instrumentations: InstrumentationConfig[];
109:   /** Optional path to a polyfill module for diagnostics_channel */
110:   dcModule?: string;
111:   /** Optional callback that that injects the code returned */
112:   injectDiagnostics?: (diagnostics: Diagnostics) => string | undefined;
113: }
114: 
115: export interface TransformResult {
116:     code: string;
117:     map?: string;
118: }
119: 
120: function getModuleVersion(basedir: string): string | undefined {
121:     try {
122:         const packageJsonPath = join(basedir, 'package.json');
123:         const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf8'));
124:         if (packageJson.version) {
125:             return packageJson.version;
126:         }
