      moduleDetails.name,
      moduleVersion,
      moduleDetails.path,
    );
    if (!transformer) return null;

    const moduleType = detectModuleType(id, code);

    if (moduleType === 'unknown') {
      failedModules.add(moduleDetails.name);
      return null;
